 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def in_bounds(r, c):
        return 0 <= r < h and 0 <= c < w

    def square_blocked(r, c, dr, dc):
        # A diagonal endpoint belonging to a filled 2x2 crossing motif
        # is not continued out through that motif.
        r2, c2 = r + dr, c + dc
        if not in_bounds(r, c) or not in_bounds(r2, c2):
            return False
        a, b = (r, c + dc), (r + dr, c)
        return (in_bounds(*a) and in_bounds(*b)
                and grid[a[0]][a[1]] != bg and grid[b[0]][b[1]] != bg)

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if in_bounds(pr, pc) and grid[pr][pc] == color:
                    continue
                run = []
                rr, cc = r, c
                while in_bounds(rr, cc) and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                # Extend each end independently, except where its seed pair
                # is part of a 2x2 diagonal crossing motif.
                for (ar, ac, br, bc, vr, vc) in (
                    (run[0][0], run[0][1], run[1][0], run[1][1], -dr, -dc),
                    (run[-2][0], run[-2][1], run[-1][0], run[-1][1], dr, dc),
                ):
                    if square_blocked(ar, ac, dr, dc):
                        continue
                    sr, sc = ar + vr, ac + vc
                    while in_bounds(sr, sc) and out[sr][sc] == bg:
                        out[sr][sc] = color
                        sr += vr
                        sc += vc
    return out
